(5532414, 799594, 51638, '<td valign="top">Technically speaking, using a zoom to give this effect might qualify as panning, but I''m going to guess it won''t be too well receive in this challenge.</td>', 'Technically speaking, using a zoom to give this effect might qualify as panning, but I''m going to guess it won''t be too well receive in this challenge.', '2009-06-17 01:33:52.000000', NULL, 1),
(5532416, 799355, 28882, '<td valign="top">haha a great shot of a three-legged dog.  i like this blur.  and you caught a great expression on his/her face.</td>', 'haha a great shot of a three-legged dog.  i like this blur.  and you caught a great expression on his/her face.', '2009-06-17 01:34:58.000000', NULL, 1),
(5532421, 800044, 51638, '<td valign="top">I guess this qualifies as motion panning as you were following the motion of the vehicle. But doing so by actually being inside the vehicle probably isn''t going to impress too many voters I suspect.</td>', 'I guess this qualifies as motion panning as you were following the motion of the vehicle. But doing so by actually being inside the vehicle probably isn''t going to impress too many voters I suspect.', '2009-06-17 01:35:55.000000', NULL, 1),
